using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class BrakePriorityProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var loc=mem["TLocParam"];int km=int.Parse(args[0]),kru=int.Parse(args[1]),saut=0,torm=0,hold=0,vcu=1;foreach(string fn in new string[]{"experimentalCprReserve","experimentalUktol1","experimentalUktol2"})typeof(TrainerIntegrationHost).GetField(fn,flags).SetValue(h,fn=="experimentalCprReserve");Marshal.WriteInt32(mem["TPult"],0x71,kru);Marshal.Copy(BitConverter.GetBytes(kru==2?5f:3f),0,IntPtr.Add(loc,9),4);Marshal.WriteByte(loc,0x7d,(byte)km);Marshal.WriteByte(loc,0x89,(byte)saut);Marshal.WriteByte(loc,0x8a,(byte)torm);Marshal.WriteByte(loc,0x8b,(byte)hold);Marshal.WriteByte(loc,0x8f,(byte)vcu);if(args.Length>2)typeof(TrainerIntegrationHost).GetField("experimentalUktol1",flags).SetValue(h,true);float initial=F(loc,9);for(int n=0;n<300;n++){Call(h,"PneumaticCycle");if(Marshal.ReadByte(loc,0x7d)!=km)throw new Exception("Selected KM not restored");}var result=new{km=km,saut=saut,torm=torm,hold=hold,vcu=vcu,initial_ur_bar=initial,final_ur_bar=F(loc,9),head_tm_bar=F(mem["TVagonParam"],0),kru=kru,active=args.Length==2,scope="Experimental reuse of native UR/reducer flow solver; NOT calibrated mechanical KRU or installed reserve mode"};string text=new JavaScriptSerializer().Serialize(result);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"KRU_flow_experiment_"+string.Join("_",args)+".json"),text);Console.WriteLine(text);return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{h.Close();h.Dispose();}}
}


